import re
from decimal import Decimal, ROUND_HALF_UP

_NUM = r"(?:\d+(?:\.\d+)?|\.\d+)"

_UNITS = {
    "s": 1, "sec": 1, "secs": 1, "second": 1, "seconds": 1,
    "m": 60, "min": 60, "mins": 60, "minute": 60, "minutes": 60,
    "h": 3600, "hr": 3600, "hrs": 3600, "hour": 3600, "hours": 3600,
    "d": 86400, "day": 86400, "days": 86400,
    "w": 604800, "wk": 604800, "wks": 604800, "week": 604800, "weeks": 604800,
}

_COMPONENT_RE = re.compile(r"\s*(" + _NUM + r")\s*([A-Za-z]+)")
_COMPONENTS_FULL_RE = re.compile(r"(?:\s*" + _NUM + r"\s*[A-Za-z]+)+\s*")
_ISO_RE = re.compile(
    r"P(?:(" + _NUM + r")W)?(?:(" + _NUM + r")D)?"
    r"(?:T(?=\d|\.\d)(?:(" + _NUM + r")H)?(?:(" + _NUM + r")M)?(?:(" + _NUM + r")S)?)?",
    re.IGNORECASE,
)
_CLOCK_RE = re.compile(r"(\d+)(?::(\d+(?:\.\d+)?))(?::(\d+(?:\.\d+)?))?")


def _round(value: Decimal) -> int:
    return int(value.quantize(Decimal(1), rounding=ROUND_HALF_UP))


def _invalid(text):
    return ValueError(f"invalid duration: {text!r}")


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise _invalid(text)
    s = text.strip()
    if not s:
        raise _invalid(text)

    # Bare non-negative integer: seconds.
    if s.isdigit() and s.isascii():
        return int(s)

    # ISO 8601 duration.
    if s[0] in "Pp":
        m = _ISO_RE.fullmatch(s)
        if not m or not any(m.groups()):
            raise _invalid(text)
        weeks, days, hours, mins, secs = (Decimal(g) if g else Decimal(0) for g in m.groups())
        total = weeks * 604800 + days * 86400 + hours * 3600 + mins * 60 + secs
        return _round(total)

    # Clock notation: hh:mm:ss or mm:ss.
    if ":" in s:
        m = _CLOCK_RE.fullmatch(s)
        if not m:
            raise _invalid(text)
        hh, mm, ss = m.groups()
        if ss is None:
            minutes, seconds = Decimal(hh), Decimal(mm)
            hours = Decimal(0)
        else:
            hours, minutes, seconds = Decimal(hh), Decimal(mm), Decimal(ss)
            if minutes >= 60:
                raise _invalid(text)
        if seconds >= 60:
            raise _invalid(text)
        return _round(hours * 3600 + minutes * 60 + seconds)

    # One or more number+unit components.
    if not _COMPONENTS_FULL_RE.fullmatch(s):
        raise _invalid(text)
    total = Decimal(0)
    for num, unit in _COMPONENT_RE.findall(s):
        key = unit.lower()
        if key not in _UNITS:
            raise _invalid(text)
        total += Decimal(num) * _UNITS[key]
    return _round(total)

